import React, { useState, useEffect } from 'react';

interface FeatureFlagConfig {
  flagName: string;
  defaultValue?: boolean;
}

function useFeatureFlag(config: FeatureFlagConfig): boolean {
  const { flagName, defaultValue = false } = config;
  const [isEnabled, setIsEnabled] = useState<boolean>(defaultValue);

  useEffect(() => {
    // Simulate API call
    const mockApiCall = () => {
      // Mock response
      const mockResponse = { [flagName]: true };
      const flagValue = mockResponse[flagName] || defaultValue;
      setIsEnabled(flagValue);
    };

    const timer = setTimeout(mockApiCall, 500);
    return () => clearTimeout(timer);
  }, [flagName, defaultValue]);

  return isEnabled;
}

function App() {
  const showNewFeature = useFeatureFlag({ flagName: 'newFeature' });

  return (
    <div>
      <h1>Feature Flag Demo</h1>
      {showNewFeature ? (
        <p>The new feature is enabled!</p>
      ) : (
        <p>The new feature is disabled.</p>
      )}
    </div>
  );
}

